package com.ragpipeline.controller;import com.ragpipeline.model.Document;import com.ragpipeline.service.DocumentIngestionService;import com.ragpipeline.service.EmbeddingService;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.util.Map;@RestController @RequestMapping("/api/v1/documents") @RequiredArgsConstructor public class DocumentController{private final DocumentIngestionService service;private final EmbeddingService embeddingService;@PostMapping(value="/ingest",consumes=MediaType.MULTIPART_FORM_DATA_VALUE)public ResponseEntity<Document> ingest(@RequestPart MultipartFile file,@RequestParam(required=false)String chunkingStrategy,@RequestParam(required=false)String organization,@RequestParam(required=false)String authority,@RequestParam(required=false)String documentType,@RequestParam(required=false)Boolean current){return ResponseEntity.accepted().body(service.ingest(file,chunkingStrategy,organization,authority,documentType,current));}@PostMapping("/reindex")public Map<String,Object> reindex(){int count=embeddingService.reindexAll();return Map.of("reindexedChunks",count);}}
